using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using System.Text.Json;
class Runner{
 static void Main(string[] args){int w=8,size=48;bool[] sample=new bool[w*w];for(int y=0;y<w;y++)for(int x=0;x<w;x++)sample[x+y*w]=(x%4==0||y%4==0);var method=typeof(Program).GetMethod("ConvChain",BindingFlags.Static|BindingFlags.NonPublic);if(method==null)throw new Exception("Original method missing");Directory.CreateDirectory(args[0]);var frames=new List<object>();int i=0;foreach(double t in new[]{0.5,1.0,2.0}){var output=(bool[])method.Invoke(null,new object[]{sample,w,w,3,t,size,64,17});int filled=output.Count(b=>b);if(output.Length!=size*size||filled==0||filled==size*size)throw new Exception("Invalid synthesis");File.WriteAllText(Path.Combine(args[0],"grid-"+i+".json"),JsonSerializer.Serialize(new{size,values=output.Select(b=>b?1:0)}));frames.Add(new{temperature=t,filled,total=size*size,seed=17,iterations=64});i++;}File.WriteAllText(Path.Combine(args[0],"result.json"),JsonSerializer.Serialize(new{frames,sampleWidth=w,sample=sample.Select(b=>b?1:0)}));Console.WriteLine("PASS original ConvChainFast synthesis, three temperatures");}
}
